@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ==========================================================================
   View transitions
   ========================================================================== */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events, so clicks made mid-animation
   would be lost. Let them fall through to the live page. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element: grid thumbnail <-> detail hero ---------------------- */

/* The blur mid-flight hides pixel interpolation as the aspect ratio changes
   from 4/3 to 1/1. 400ms is slow enough to read, fast enough to feel direct. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}

::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal: skeleton -> content -------------------------------- */

/* Asymmetric on purpose: the skeleton leaves quickly so it stops competing for
   attention, and the real content arrives more gently, only fading in once the
   skeleton has finished leaving. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* --- Directional navigation --------------------------------------------- */

/* Forward navigation carries content to the left, back navigation to the
   right. 60px is enough to signal direction without asking the user to track
   a fast-moving element across the viewport. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* --- Reduced motion ----------------------------------------------------- */

/* Zeroing the durations falls back to the browser default: an instant swap.
   The looping skeleton pulse stops too. */
@media (prefers-reduced-motion: reduce) {
